def _audit(profile, fabric, proposal):
    M = get_model(profile, fabric)
    cal = M.cal
    if not isinstance(proposal, dict):
        return {"valid": False}
    st = proposal.get('status')
    if cal.cycle is not None:
        if st == 'inconsistent':
            return {"valid": check_cycle(cal, proposal.get('cycle'))}
        return {"valid": False}
    if st == 'inconsistent':
        return {"valid": check_cycle(cal, proposal.get('cycle'))}
    if st != 'ok':
        return {"valid": False}
    F = M.F
    if not check_calib_artifact(cal, proposal.get('profile')):
        return {"valid": False}
    if not _is_int(proposal.get('period_rounds')) or proposal['period_rounds'] != F.P:
        return {"valid": False}
    true_peaks = plan_peaks(M)
    pk = proposal.get('peaks_as')
    if not isinstance(pk, list) or len(pk) != len(F.guards):
        return {"valid": False}
    for got, want in zip(pk, true_peaks):
        if want is None:
            if got is not None:
                return {"valid": False}
        else:
            if not _is_int(got) or got != want:
                return {"valid": False}
    true_guard = select_guard(F, true_peaks)
    guard = proposal.get('guard_ns')
    if true_guard is None:
        if guard is not None:
            return {"valid": False}
        if (proposal.get('bounds_as') is not None
                or proposal.get('age_rounds') is not None
                or proposal.get('pred') is not None
                or proposal.get('warmup_cycle') is not None):
            return {"valid": False}
        return {"valid": True}
    if not _is_int(guard) or guard != true_guard:
        return {"valid": False}
    if not _check_plan_matrices(M, guard, proposal):
        return {"valid": False}
    wk = proposal.get('warmup_cycle')
    true_warm = warmup_of(M, true_guard)
    if not _is_int(wk) or wk != true_warm:
        return {"valid": False}
    return {"valid": True}


def _check_plan_matrices(M, g, proposal):
    F = M.F
    cal = M.cal
    N, P, V = F.N, F.P, F.V
    bnd = proposal.get('bounds_as')
    age = proposal.get('age_rounds')
    pre = proposal.get('pred')
    for mat in (bnd, age, pre):
        if not isinstance(mat, list) or len(mat) != P:
            return False
    Lb = [None] * V
    La = [None] * V
    Lp = [None] * V
    for p in range(P):
        rb = bnd[p]
        ra = age[p]
        rp = pre[p]
        for mat in (rb, ra, rp):
            if not isinstance(mat, list) or len(mat) != N:
                return False
        base = p * N
        for i in range(N):
            v1 = rb[i]
            v2 = ra[i]
            v3 = rp[i]
            c = base + i
            if v1 is None or v2 is None:
                if v1 is not None or v2 is not None:
                    return False
                if v3 is not None:
                    return False
                Lb[c] = None
                La[c] = None
                Lp[c] = None
            else:
                if not _is_int(v1) or not _is_int(v2):
                    return False
                if v1 < 0 or v2 < 0:
                    return False
                if not isinstance(v3, list) or len(v3) != 2:
                    return False
                if not _is_int(v3[0]) or not _is_int(v3[1]):
                    return False
                Lb[c] = v1
                La[c] = v2
                Lp[c] = (v3[0], v3[1])
    # anchors are labelled (0,0) with no predecessor
    for c in F.anchor_cells:
        if Lb[c] != 0 or La[c] != 0 or Lp[c] is not None:
            return False
    # attaining witness chains: exact labels, valid steps, end at anchors
    state = [0] * V  # 0 unknown, 1 on current walk, 2 verified
    for start in range(V):
        if Lb[start] is None or state[start]:
            continue
        path = []
        cur = start
        while True:
            if Lb[cur] is None:
                return False
            if state[cur] == 2:
                break
            if state[cur] == 1:
                return False  # witness cycle
            state[cur] = 1
            path.append(cur)
            pv = Lp[cur]
            if pv is None:
                break
            v = pv[0]
            kind = pv[1]
            if not _is_int(v) or not _is_int(kind):
                return False
            if v < 0 or v >= V:
                return False
            if Lb[v] is None or La[v] is None:
                return False
            pc, ic = divmod(cur, N)
            ps, isrc = divmod(v, N)
            res = F.step_info(cal, ps, isrc, kind, g)
            if res is None:
                return False
            dst_node, dst_phase, cost, dt = res
            if dst_node != ic or dst_phase != pc:
                return False
            if Lb[cur] != Lb[v] + cost or La[cur] != La[v] + dt:
                return False
            cur = v
        for node in path:
            if state[node] != 2:
                if Lp[node] is None and not F.anchor_mask[node]:
                    return False
                state[node] = 2
    # closure inequalities over every allowed step from finitely labelled cells
    def close(u, cost, dt, v):
        if Lb[u] is None:
            return True
        if Lb[v] is None or La[v] is None:
            return False
        sb = Lb[u] + cost
        sa = La[u] + dt
        db = Lb[v]
        da = La[v]
        return db < sb or (db == sb and da <= sa)

    drift = F.drift_as
    for u in range(V):
        if Lb[u] is None:
            continue
        p, i = divmod(u, N)
        v = ((p + 1) % P) * N + i
        if not close(u, drift[u], 1, v):
            return False
    for (p, src, dst, dt, cost, code, margin) in F.edges_all:
        if margin < g:
            continue
        u = p * N + src
        if Lb[u] is None:
            continue
        v = ((p + dt) % P) * N + dst
        if not close(u, cost, dt, v):
            return False
    return True


def op_audit(profile, fabric, proposal):
    try:
        return _audit(profile, fabric, proposal)
    except Exception:
        return {"valid": False}
